use std::fs
use std::json

struct Item {
    sku: string,
    qty: int,
    price: float,
}

struct Order {
    id: int,
    customer: string,
    items: Vec<Item>,
    note: Option<string>,
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let parsed = json.parse_string::<Vec<Order>>(text)
    match parsed {
        Ok(orders) => {
            let mut names: Vec<string> = []
            let mut sums: Vec<float> = []
            for o in orders {
                let mut t = 0.0
                for it in o.items {
                    let q: float = it.qty as float
                    let p: float = it.price
                    t = t + q * p
                }
                let mut found = false
                let mut i = 0
                while i < names.len() {
                    if names[i] == o.customer {
                        sums[i] = sums[i] + t
                        found = true
                    }
                    i += 1
                }
                if !found {
                    names.push(o.customer)
                    sums.push(t)
                }
            }
            let n = names.len()
            let mut a = 0
            while a < n {
                let mut b = a + 1
                while b < n {
                    if names[b] < names[a] {
                        let tn = names[a]
                        names[a] = names[b]
                        names[b] = tn
                        let ts = sums[a]
                        sums[a] = sums[b]
                        sums[b] = ts
                    }
                    b += 1
                }
                a += 1
            }
            let mut k = 0
            while k < n {
                let nm = names[k]
                let v = sums[k]
                println("${nm} ${v:.2}")
                k += 1
            }
        }
        Err(e) => {
            println("invalid input")
            std::process::exit(1)
        }
    }
}

